pub fn vec_len<T>(x: &Vec<T>) -> usize {
    x.len()
}

pub fn numpy_log10(x: Vec<f32>) -> Vec<f32> {
    // Input is assumed non-empty, but the length property holds regardless.
    let n = x.len();
    let mut result: Vec<f32> = Vec::with_capacity(n);

    let mut i: usize = 0;
    while i < n {
        // Safe: i is always < n, so indexing is in-bounds.
        result.push(x[i]);
        i += 1;
    }

    // Ensure returned vector length matches input length.
    debug_assert_eq!(result.len(), n);
    result
}